// Backward compatibility with state written by flow at commit b913f36, the commit the
// owner's running sessions used before playbooks moved out of the repo. The fixture
// test/fixtures/state-b913f36/ was written by b913f36's own flow and keeper (with the
// fake claude) and its two expected files were captured by running b913f36 on it; they
// are never regenerated by code (see the fixture's README.md). This test runs today's
// flow and keeper on the same input, with the fixture's `legacy` playbook only in the
// private directory ~/.product-dev-flow/playbooks of a temp HOME.

import assert from "node:assert/strict";
import { spawnSync } from "node:child_process";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import test from "node:test";
import { FLOW, ROOT, gitIn, removeTempDir } from "./helpers.mjs";

const FIXTURE = path.join(ROOT, "test", "fixtures", "state-b913f36");
const KEEPER = path.join(ROOT, "keeper", "flow-keeper.mjs");
// The fixture's records were written with this FLOW_NOW.
const FIXTURE_NOW = "2026-11-20T09:00:00Z";

// Copies a fixture folder, putting the temp root in place of __ROOT__ and real pids in
// place of the pid placeholders (quoted in the fixture so its JSON stays valid).
function copyFixture(from, to, { root, alive, dead }) {
  fs.mkdirSync(to, { recursive: true });
  for (const entry of fs.readdirSync(from, { withFileTypes: true })) {
    const source = path.join(from, entry.name);
    const target = path.join(to, entry.name);
    if (entry.isDirectory()) {
      copyFixture(source, target, { root, alive, dead });
      continue;
    }
    const text = fs.readFileSync(source, "utf8");
    fs.writeFileSync(target, text.split("__ROOT__").join(root).split('"__ALIVE_PID__"').join(String(alive)).split('"__DEAD_PID__"').join(String(dead)));
  }
}

function prepare(t) {
  const root = fs.realpathSync(fs.mkdtempSync(path.join(os.tmpdir(), "flow-compat-")));
  t.after(() => removeTempDir(root));
  // A pid that is dead for sure: a child this test started and reaped.
  const dead = spawnSync(process.execPath, ["-e", ""]).pid;
  const values = { root, alive: process.pid, dead };

  // The scratch repo the legacy playbook points at. dev/demo-2 (the branch p-demo-2's
  // cleanup left) has been merged since: origin/main contains it.
  const repo = path.join(root, "repo");
  fs.mkdirSync(repo);
  gitIn(repo, ["init", "-q", "-b", "main"]);
  fs.writeFileSync(path.join(repo, "README.md"), "scratch repo\n");
  gitIn(repo, ["add", "-A"]);
  gitIn(repo, ["commit", "-q", "-m", "scratch"]);
  gitIn(repo, ["branch", "dev/demo-2"]);
  gitIn(repo, ["checkout", "-q", "dev/demo-2"]);
  fs.writeFileSync(path.join(repo, "demo-2.txt"), "lane work\n");
  gitIn(repo, ["add", "-A"]);
  gitIn(repo, ["commit", "-q", "-m", "demo-2 work"]);
  gitIn(repo, ["checkout", "-q", "main"]);
  gitIn(repo, ["update-ref", "refs/remotes/origin/main", "dev/demo-2"]);

  copyFixture(path.join(FIXTURE, "state"), path.join(root, "state"), values);
  copyFixture(path.join(FIXTURE, "claude"), path.join(root, "claude"), values);
  copyFixture(path.join(FIXTURE, "legacy"), path.join(root, ".product-dev-flow", "playbooks", "legacy"), values);

  // The worktrees of the sessions whose jobs are still there (p-demo-2's went with its cleanup).
  const state = path.join(root, "state");
  for (const slug of fs.readdirSync(path.join(state, "sessions")).sort()) {
    const record = JSON.parse(fs.readFileSync(path.join(state, "sessions", slug, "record.json"), "utf8"));
    if (record.cleanedAt) continue;
    gitIn(repo, ["worktree", "add", "-q", "-b", `worktree-${record.worktree}`, path.join(repo, ".claude", "worktrees", record.worktree), "main"]);
  }
  // The state dir is a git repo; a nested .git cannot be checked in, so it is made here.
  gitIn(state, ["init", "-q", "-b", "main"]);
  gitIn(state, ["add", "-A"]);
  gitIn(state, ["commit", "-q", "-m", "state written by b913f36"]);

  const roles = path.join(root, "roles");
  fs.mkdirSync(roles);
  const env = { ...process.env };
  for (const key of Object.keys(env)) if (key.startsWith("FLOW_") || key.startsWith("FAKE_CLAUDE")) delete env[key];
  Object.assign(env, {
    HOME: root,
    FLOW_STATE: state,
    FLOW_CLAUDE: path.join(FIXTURE, "fake-claude.mjs"),
    FLOW_CLAUDE_HOME: path.join(root, "claude"),
    FLOW_ROLES: roles,
    FLOW_NOW: FIXTURE_NOW,
  });
  return { root, env };
}

function run(script, args, env) {
  const result = spawnSync(process.execPath, [script, ...args], { env, encoding: "utf8", timeout: 120_000 });
  return { status: result.status, stdout: result.stdout, stderr: result.stderr };
}

const expected = (file) => fs.readFileSync(path.join(FIXTURE, file), "utf8");

// protects: state written by b913f36 (records with playbook "legacy", its plan, notes and cards, and the claude home it left) reads the same under today's flow with the playbook moved to ~/.product-dev-flow/playbooks: `flow tree --all` byte for byte, and the keeper's --dry-run decisions line for line (ISO timestamp prefix stripped), against files captured from b913f36
// fails_when: a record field, the tree format or a keeper decision changes meaning for old state, or the keeper cannot find a playbook that now lives only in the private directory (cleanup and branch checks then log "skipped")
// no_claim: the decision kinds this fixture exercises are resume (i-1 down), pin (demo-1-build), cleanup (p-demo-1 archived, clean and pushed), branch follow (p-demo-2's dev/demo-2 now merged) and orphan (demo-1-build under archived p-demo-1); not exercised: 4090 notices, held sessions, dirty or unpushed worktrees, fetch failures, any non-dry-run write; the expected files are only as right as the b913f36 run that produced them
test("state written by b913f36 reads the same", (t) => {
  const { root, env } = prepare(t);

  const tree = run(FLOW, ["tree", "--all"], env);
  assert.equal(tree.status, 0, tree.stderr);
  assert.equal(tree.stdout, expected("tree-all.expected.txt"));

  const keeper = run(KEEPER, ["--dry-run"], env);
  // A failed run logs to stdout ("keeper run failed: …") and exits 1.
  assert.equal(keeper.status, 0, `${keeper.stderr}${keeper.stdout}`);
  assert.equal(keeper.stderr, "");
  // Paths in the log are the temp root's; the expected file holds __ROOT__.
  const lines = keeper.stdout.split("\n").map((line) => line.replace(/^\[\d{4}-\d\d-\d\dT\d\d:\d\d:\d\d\.\d{3}Z\] /, "").split(root).join("__ROOT__"));
  assert.equal(lines.join("\n"), expected("keeper-dry-run.expected.txt"));

  // A recapture that lost a decision kind would still match itself; these keep the gate honest.
  for (const pattern of [/: down, starting it again$/, /: pinned$/, /^\(dry run\) p-demo-1: clean and pushed; would claude rm /, /^\(dry run\) p-demo-2: branch dev\/demo-2 merged into origin\/main; would delete it/, /^\(dry run\) ORPHAN /]) {
    assert.ok(lines.some((line) => pattern.test(line)), `no keeper line matches ${pattern}`);
  }
});
